  return memberRepo.listMembers(input);
}

/**
 * Role changes carry two rules the permission matrix cannot express:
 * nobody may grant a role above their own, and the last owner may not be
 * demoted. Both are checked after `can()` has had its say.
 */
export async function updateMemberRole(
  actor: Actor,
  input: UpdateMemberRoleInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:update_role", memberResource(member));

  if (!hasRoleAtLeast(actor.role, input.role)) {
    throw new Error(
      `A ${actor.role} cannot grant the ${input.role} role`,
    );
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });

  return updated;
}

/**
 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 * demotion — a removed owner is a demotion to "no role at all".
 */
export async function removeMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Exported because both the demote and the remove path need
 * it, and the invariant must not be stated twice.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter((row) => row.id !== memberId);
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}

