/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";
/**
 * Test double for `@/lib/id` (owner E).
 *
 * The server suite needs ids that are valid ULIDs *and* reproducible, so a
 * failing assertion names the same row on every run. Counter-based rather than
 * random for exactly that reason.
 */
const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const ULID_LENGTH = 26;

let counter = 0;

export function newId(): string {
  counter += 1;
  return encode(counter);
}

export function isUlid(value: string): boolean {
  return (
    value.length === ULID_LENGTH &&
    [...value].every((char) => ULID_ALPHABET.includes(char.toUpperCase()))
  );
}

export function idFactory(seed: number): () => string {
  let local = seed;
  return () => {
    local += 1;
    return encode(local);
  };
}

/** Test-only: rewinds the counter so each file starts from the same ids. */
export function resetIds(): void {
  counter = 0;
}

function encode(value: number): string {
  let remaining = value;
  let out = "";

  while (out.length < ULID_LENGTH) {
    out = `${ULID_ALPHABET[remaining % 32] ?? "0"}${out}`;
    remaining = Math.floor(remaining / 32);
  }

  return out.slice(-ULID_LENGTH);
}
/**
 * ULID generation and validation. Every branded id in the app is produced
 * here, so ids sort lexicographically by creation time and the repositories
 * can use them as pagination cursors without a separate sort column.
 */
/** Crockford base32, minus I, L, O and U. */
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const TIME_LENGTH = 10;
const RANDOM_LENGTH = 16;

const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

function encodeTime(time: number): string {
  let remaining = time;
  let out = "";
  for (let i = 0; i < TIME_LENGTH; i += 1) {
    const mod = remaining % 32;
    out = ALPHABET[mod] + out;
    remaining = (remaining - mod) / 32;
  }
  return out;
}

function encodeRandom(next: () => number): string {
  let out = "";
  for (let i = 0; i < RANDOM_LENGTH; i += 1) {
    out += ALPHABET[next() % 32];
  }
  return out;
}

/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same
 *  implementation runs on the server, in the browser and on the edge. */
export function newId(): string {
  const bytes = new Uint8Array(RANDOM_LENGTH);
  globalThis.crypto.getRandomValues(bytes);
  let cursor = 0;
  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);
}

