/**
 * Ownership handover offers. Every read and write is filtered by `orgId`; a
 * row is never deleted — it moves from `pending` to a resolved status.
 */
import { and, eq, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

/** The offer that has not been resolved yet, lapsed or not; at most one exists. */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
  expiresAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      createdAt,
      resolvedAt: null,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/**
 * Moves a still-pending offer to `status`. Resolves to `null` when the offer
 * was no longer pending, which is how a lost race shows up to the caller.
 */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/** Withdraws the open offer, if any, in which `userId` is either side. */
export async function cancelPendingHandoverInvolving(
  orgId: OrgId,
  userId: UserId,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .returning()
    .get();
  return row ? toOwnershipHandover(row) : null;
}
