/**
 * Ownership handover: offer, accept, decline, withdraw, lapse.
 *
 * Implemented by `@/server/services/organization-service`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError, toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as orgService from "@/server/services/organization-service";
import { resolveActor } from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import * as activityService from "@/server/services/activity-service";
import * as userRepo from "@/server/repositories/user-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Role } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let detachAudit: Unsubscribe;
const detachers: Unsubscribe[] = [];
let slugCounter = 0;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachAudit = registerActivityListeners();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

function freshTenant(): Promise<Tenant> {
  slugCounter += 1;
  return createTenant(`handover-${slugCounter}`, "growth");
}

async function roleOf(orgId: OrgId, userId: UserId): Promise<Role | undefined> {
  return (await memberRepo.findMember(orgId, userId))?.role;
}

describe("initiateOwnershipHandover", () => {
  it("opens an offer that lapses exactly seven days later and shows it to every member", async () => {
    const tenant = await freshTenant();

    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    expect(offer).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.admin,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(7 * DAY_MS);

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      const seen = await orgService.getPendingOwnershipHandover(tenant.actors[role], tenant.org.id);
      expect(seen).toEqual(offer);
    }
  });

  it("alerts only the offered member", async () => {
    const tenant = await freshTenant();

    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const inbox = async (role: Role) =>
      notificationService.listNotifications(tenant.actors[role], {
        orgId: tenant.org.id,
        recipientId: tenant.userIds[role],
        unreadOnly: false,
        limit: 25,
        cursor: null,
      });

    expect((await inbox("member")).items.map((row) => row.kind)).toEqual(["ownership_handover"]);
    for (const role of ["owner", "admin", "viewer"] as const) {
      expect((await inbox(role)).items).toHaveLength(0);
    }
  });

  it("refuses everyone but the recorded owner, even one holding the owner role", async () => {
    const tenant = await freshTenant();
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberRepo.updateMemberRole(tenant.org.id, admin!.id, "owner");
    const secondOwner = { ...tenant.actors.admin, role: "owner" as const };

    await expect(
      orgService.initiateOwnershipHandover(secondOwner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses the owner as target, and targets outside the active membership", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    const stranger = await userRepo.insertUser({ email: "x@nowhere.test", name: "X", passwordHash: "seed" });

    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.owner),
    ).rejects.toMatchObject({ code: "conflict", reason: "self" });

    for (const target of [stranger.id, other.userIds.admin]) {
      await expect(
        orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, target),
      ).rejects.toBeInstanceOf(NotFoundError);
    }

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer!.id,
    });
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("allows one open offer at a time, and a new one once it is withdrawn or declined", async () => {
    const tenant = await freshTenant();
    const { owner } = tenant.actors;
    await orgService.initiateOwnershipHandover(owner, tenant.org.id, tenant.userIds.admin);

    const again = orgService.initiateOwnershipHandover(owner, tenant.org.id, tenant.userIds.member);
    await expect(again).rejects.toBeInstanceOf(OwnershipHandoverError);
    await expect(again).rejects.toMatchObject({ reason: "pending_exists" });

    const withdrawn = await orgService.cancelOwnershipHandover(owner, tenant.org.id);
    expect(withdrawn.status).toBe("canceled");
    expect(withdrawn.resolvedAt).not.toBeNull();
    expect(await orgService.getPendingOwnershipHandover(owner, tenant.org.id)).toBeNull();

    await orgService.initiateOwnershipHandover(owner, tenant.org.id, tenant.userIds.member);
    const declined = await orgService.declineOwnershipHandover(tenant.actors.member, tenant.org.id);
    expect(declined.status).toBe("declined");
    expect(await orgService.getPendingOwnershipHandover(owner, tenant.org.id)).toBeNull();

    await expect(
      orgService.initiateOwnershipHandover(owner, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toMatchObject({ status: "pending" });
  });
});

describe("acceptOwnershipHandover", () => {
  it("makes the offered member the owner and steps the previous owner down to admin", async () => {
    const tenant = await freshTenant();
    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");

    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
    const org = await orgService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id);

    expect(org.ownerId).toBe(tenant.userIds.viewer);
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(tenant.userIds.viewer);
    expect(await roleOf(tenant.org.id, tenant.userIds.viewer)).toBe("owner");
    expect(await roleOf(tenant.org.id, tenant.userIds.owner)).toBe("admin");
    expect(await orgService.getPendingOwnershipHandover(tenant.actors.admin, tenant.org.id)).toBeNull();

    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(roleChanges).toHaveLength(2);
    expect(roleChanges).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ memberId: viewerMember!.id, from: "viewer", to: "owner" }),
        expect.objectContaining({ memberId: ownerMember!.id, from: "owner", to: "admin" }),
      ]),
    );
    expect(transfers).toHaveLength(1);
    expect(transfers[0]).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.viewer,
    });
    for (const event of [...roleChanges, ...transfers]) {
      expect(event.actorId).toBe(tenant.userIds.viewer);
    }
  });

  it("only demotes the previous owner when the offered member already owns", async () => {
    const tenant = await freshTenant();
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberRepo.updateMemberRole(tenant.org.id, admin!.id, "owner");
    const roleChanges = capture("member.role_changed");

    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    await orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);

    expect(roleChanges).toHaveLength(1);
    expect(roleChanges[0]).toMatchObject({ from: "owner", to: "admin" });
    expect(await roleOf(tenant.org.id, tenant.userIds.owner)).toBe("admin");
    expect(await roleOf(tenant.org.id, tenant.userIds.admin)).toBe("owner");
  });

  it("leaves the previous owner's role alone when they no longer hold the owner role", async () => {
    const tenant = await freshTenant();
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    await memberRepo.updateMemberRole(tenant.org.id, admin!.id, "owner");
    await memberRepo.updateMemberRole(tenant.org.id, owner!.id, "member");
    const roleChanges = capture("member.role_changed");

    await orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id);

    expect(roleChanges).toHaveLength(1);
    expect(await roleOf(tenant.org.id, tenant.userIds.owner)).toBe("member");
    expect(await roleOf(tenant.org.id, tenant.userIds.member)).toBe("owner");
  });

  it("is audited as an organization action carrying both users", async () => {
    const tenant = await freshTenant();

    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    await orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);

    const page = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["organization.ownership_transferred"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.admin },
    });
  });

  it("makes the alerts, billing and removal rules follow the new owner", async () => {
    const tenant = await freshTenant();
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    await orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);

    const newOwner = await resolveActor(tenant.userIds.admin, tenant.org.id);
    const oldOwner = await resolveActor(tenant.userIds.owner, tenant.org.id);
    const change = { orgId: tenant.org.id, plan: "enterprise" as const, interval: "monthly" as const };

    // Even an actor minted before the handover is judged by the stored role.
    await expect(billingService.changePlan(tenant.actors.owner, change)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(billingService.changePlan(oldOwner!, change)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(billingService.changePlan(newOwner!, change)).resolves.toMatchObject({
      plan: "enterprise",
    });

    // New members are announced to the new owner only.
    await notificationService.notify(tenant.org.id, "member_joined", [(await orgRepo.findOrgById(tenant.org.id))!.ownerId], {
      title: "A new member joined",
      body: "x",
      href: "/settings/members",
      actorId: tenant.userIds.viewer,
    });

    // The previous owner is an admin now and can be removed like one.
    const previous = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    await expect(
      memberService.removeMember(newOwner!, { orgId: tenant.org.id, memberId: previous!.id }),
    ).resolves.toMatchObject({ userId: tenant.userIds.owner });
  });
});

describe("refusals", () => {
  it("tells anyone but the offered member there is nothing pending", async () => {
    const tenant = await freshTenant();
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);

    for (const role of ["owner", "member", "viewer"] as const) {
      await expect(orgService.acceptOwnershipHandover(tenant.actors[role], tenant.org.id)).rejects.toMatchObject({
        reason: "nothing_pending",
      });
      await expect(orgService.declineOwnershipHandover(tenant.actors[role], tenant.org.id)).rejects.toMatchObject({
        reason: "nothing_pending",
      });
    }
    expect(await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).not.toBeNull();
  });

  it("has nothing pending once an offer is resolved or when none was made", async () => {
    const tenant = await freshTenant();
    const { owner, admin } = tenant.actors;

    await expect(orgService.cancelOwnershipHandover(owner, tenant.org.id)).rejects.toMatchObject({
      reason: "nothing_pending",
    });
    await expect(orgService.acceptOwnershipHandover(admin, tenant.org.id)).rejects.toMatchObject({
      reason: "nothing_pending",
    });

    await orgService.initiateOwnershipHandover(owner, tenant.org.id, tenant.userIds.admin);
    await orgService.acceptOwnershipHandover(admin, tenant.org.id);
    await expect(orgService.acceptOwnershipHandover(admin, tenant.org.id)).rejects.toMatchObject({
      reason: "nothing_pending",
    });

    const other = await freshTenant();
    await orgService.initiateOwnershipHandover(other.actors.owner, other.org.id, other.userIds.admin);
    await orgService.cancelOwnershipHandover(other.actors.owner, other.org.id);
    await expect(orgService.declineOwnershipHandover(other.actors.admin, other.org.id)).rejects.toMatchObject({
      reason: "nothing_pending",
    });
  });

  it("only lets the recorded owner withdraw", async () => {
    const tenant = await freshTenant();
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);

    await expect(
      orgService.cancelOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).not.toBeNull();
  });

  it("scopes every operation to the actor's workspace", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);

    const foreign = other.actors.owner;
    const calls = [
      () => orgService.initiateOwnershipHandover(foreign, tenant.org.id, tenant.userIds.member),
      () => orgService.acceptOwnershipHandover(foreign, tenant.org.id),
      () => orgService.declineOwnershipHandover(foreign, tenant.org.id),
      () => orgService.cancelOwnershipHandover(foreign, tenant.org.id),
      () => orgService.getPendingOwnershipHandover(foreign, tenant.org.id),
    ];
    for (const call of calls) {
      await expect(call()).rejects.toBeInstanceOf(TenantScopeError);
    }
    expect(await orgService.getPendingOwnershipHandover(other.actors.owner, other.org.id)).toBeNull();
  });
});

describe("lapse", () => {
  it("can be acted on until the seventh day and not from it", async () => {
    const tenant = await freshTenant();
    vi.useFakeTimers({ toFake: ["Date"] });
    const start = new Date("2026-05-01T10:00:00.000Z");
    vi.setSystemTime(start);

    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);

    vi.setSystemTime(new Date(start.getTime() + 7 * DAY_MS - 1));
    expect(await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).not.toBeNull();

    vi.setSystemTime(new Date(start.getTime() + 7 * DAY_MS));
    expect(await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).toBeNull();
    await expect(orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id)).rejects.toMatchObject({
      reason: "expired",
    });
    await expect(orgService.declineOwnershipHandover(tenant.actors.admin, tenant.org.id)).rejects.toMatchObject({
      reason: "expired",
    });
    await expect(orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id)).rejects.toMatchObject({
      reason: "nothing_pending",
    });

    // Acting on the lapsed offer changed nothing.
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(tenant.userIds.owner);
    expect(await roleOf(tenant.org.id, tenant.userIds.owner)).toBe("owner");
    expect(await roleOf(tenant.org.id, tenant.userIds.admin)).toBe("admin");

    // ...and it no longer blocks a new offer.
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toMatchObject({ toUserId: tenant.userIds.member, status: "pending" });
  });
});

describe("a member leaving", () => {
  it("withdraws the offer when the offered member is removed", async () => {
    const tenant = await freshTenant();
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: member!.id });

    expect(await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).toBeNull();
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
    ).resolves.toMatchObject({ status: "pending" });
  });

  it("withdraws the offer when the offering owner is removed", async () => {
    const tenant = await freshTenant();
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    await memberRepo.updateMemberRole(tenant.org.id, admin!.id, "owner");
    const secondOwner = await resolveActor(tenant.userIds.admin, tenant.org.id);
    await memberService.removeMember(secondOwner!, { orgId: tenant.org.id, memberId: owner!.id });

    expect(await orgService.getPendingOwnershipHandover(secondOwner!, tenant.org.id)).toBeNull();
    await expect(orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id)).rejects.toMatchObject({
      reason: "nothing_pending",
    });
  });
});

describe("OwnershipHandoverError", () => {
  it("maps to the conflict code", () => {
    const error = new OwnershipHandoverError("expired");
    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("conflict");
    expect(error.reason).toBe("expired");
    expect(toAppError(error)).toMatchObject({ code: "conflict", meta: { reason: "expired" } });
  });
});
